from pathlib import Path

def venv_report(env_root, platform, prefix, base_prefix):
    if platform == 'windows':
        python = Path(env_root) / 'Scripts' / 'python.exe'
    elif platform == 'posix':
        python = Path(env_root) / 'bin' / 'python'
    else:
        raise ValueError('unsupported platform')
    return {'python_path': python, 'in_venv': prefix != base_prefix}
